INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Einfügeanomalie nur bei relationalen Datenbanken möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Normalisierung betrifft RDBMS"}, {"text": "Nein", "correct": false, "because": "Hauptsächlich RDBMS"}]'),
('00000000-0000-0000-0000-000000000000', 'Was beschreibt eine Einfügeanomalie?', 3, '[{"text": "Probleme beim Einfügen neuer Daten", "correct": true, "because": "Fehlende Schlüsselwerte"}, {"text": "Datenverlust bei Löschung", "correct": false, "because": "Das ist Löschungsanomalie"}, {"text": "Fehler bei Updates", "correct": false, "because": "Das ist Änderungsanomalie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedingungen führen zu einer Einfügeanomalie?', 5, '[{"text": "Nicht normalisierte Daten", "correct": true, "because": "Redundanzen"}, {"text": "Fehlende Schlüsselwerte", "correct": true, "because": "Einfügen unmöglich"}, {"text": "Vollständige Normalisierung", "correct": false, "because": "Vermeidet Anomalien"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einfügeanomalien treten bei fehlenden Primärschlüsseln auf. b) Sie betreffen nur große Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Größe irrelevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Einfügeanomalie?', 4, '[{"text": "Datenintegrität", "correct": false, "because": "Kernproblem"}, {"text": "Tabellenstruktur", "correct": false, "because": "Ursache der Anomalie"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Einfügeanomalie durch Normalisierung vermieden wird?', 2, '[{"text": "Ja", "correct": true, "because": "Struktur optimieren"}, {"text": "Nein", "correct": false, "because": "Normalisierung hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Normalisierungsform verhindert Einfügeanomalien?', 3, '[{"text": "2NF", "correct": true, "because": "Teilabhängigkeiten beseitigen"}, {"text": "1NF", "correct": false, "because": "Nur Grundlage"}, {"text": "4NF", "correct": false, "because": "Spätere Stufe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen hat eine Einfügeanomalie?', 5, '[{"text": "Unvollständige Daten", "correct": true, "because": "Einfügen nicht möglich"}, {"text": "Inkonsistenz", "correct": true, "because": "Datenfehler"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Einfügeanomalien entstehen bei schlechter Normalisierung. b) Sie sind unvermeidbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vermeidbar durch Normalisierung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Einfügeanomalien zu vermeiden?', 4, '[{"text": "Primärschlüssel", "correct": false, "because": "Identifikation nötig"}, {"text": "Normalisierung", "correct": false, "because": "Struktur verbessern"}, {"text": "Papierdokumente", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Einfügeanomalie ein Problem der Datenbankstruktur?', 2, '[{"text": "Ja", "correct": true, "because": "Schlechte Normalisierung"}, {"text": "Nein", "correct": false, "because": "Strukturursache"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenbankprobleme sind mit Einfügeanomalien verwandt?', 4, '[{"text": "Änderungsanomalie", "correct": true, "because": "Inkonsistenz bei Updates"}, {"text": "Löschungsanomalie", "correct": true, "because": "Datenverlust"}, {"text": "Netzwerkanomalie", "correct": false, "because": "Kein Datenbankproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Einfügeanomalien nur bei großen Datenmengen auftreten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Strukturproblem"}, {"text": "Ja", "correct": false, "because": "Unabhängig von Menge"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, um Einfügeanomalien zu verhindern?', 3, '[{"text": "Normalisierung", "correct": true, "because": "Struktur optimieren"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einfügeanomalien entstehen durch Redundanzen. b) Sie sind nur in NoSQL-Datenbanken möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NoSQL weniger betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen verhindern Einfügeanomalien?', 5, '[{"text": "Primärschlüssel einführen", "correct": true, "because": "Eindeutigkeit"}, {"text": "Tabellen trennen", "correct": true, "because": "Normalisierung"}, {"text": "Daten duplizieren", "correct": false, "because": "Verursacht Anomalien"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Einfügeanomalie unwichtig?', 3, '[{"text": "Tabellenstruktur", "correct": false, "because": "Ursache"}, {"text": "Datenkonsistenz", "correct": false, "because": "Betroffen"}, {"text": "Monitorgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können Einfügeanomalien durch Schlüsselwerte behoben werden?', 3, '[{"text": "Ja", "correct": true, "because": "Primärschlüssel helfen"}, {"text": "Nein", "correct": false, "because": "Lösung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Einfügeanomalien Datenverlust verursachen?', 2, '[{"text": "Nein", "correct": true, "because": "Einfügen blockiert"}, {"text": "Ja", "correct": false, "because": "Löschungsanomalie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für eine Einfügeanomalie zentral?', 4, '[{"text": "Nicht normalisierte Struktur", "correct": true, "because": "Ursache"}, {"text": "Perfekte Normalisierung", "correct": false, "because": "Vermeidet"}, {"text": "Hardwarefehler", "correct": false, "because": "Softwareproblem"}]');
